@Test
    public void testCanonicalize() {
        assertEquals("/", ZNodePath.canonicalize("/"));
        assertEquals("/", ZNodePath.canonicalize("//"));
        assertEquals("/", ZNodePath.canonicalize("///"));
        assertEquals("/a", ZNodePath.canonicalize("/a"));
        assertEquals("/a", ZNodePath.canonicalize("/a/"));
        assertEquals("/", ZNodePath.canonicalize("/."));
        assertEquals("/a", ZNodePath.canonicalize("/a/."));
        assertEquals("/", ZNodePath.canonicalize("/a/.."));
    }

